    }

    method write_log(off : int, val : int)
        modifies this;
        modifies log_;
        requires 0 <= off <= |gs.log|;
        requires mem_ != log_;
        requires ghost_state_inv(gs);
        requires ghost_state_equiv(gs);
        requires off == 0 ==> 0 <= val * 2 < |gs.log|;
