        requires ghost_state_equiv(gs);
        requires ghost_tx_inv(gs);
        requires old_mem_equiv(gs);
        requires 0 <= log_[0] * 2 + 3 < log_.Length;
        ensures ghost_state_equiv(gs);
        ensures ghost_tx_inv(gs);
