        if (log_len > 0) {
            var i := log_len - 1;

            ghost var gs0 := gs;
            while i >= 0
                modifies mem_;
                modifies this;
                invariant log_ == old(log_);
                invariant mem_ == old(mem_);
                invariant unchanged(log_);
