413         assert log_off + 1 > 0;
414         assert ghost_state_equiv(gs);
415         assert mem_ != log_;
416         var old_val := mem_[offset];
417         assert old_val == gs.mem[offset];
418         write_log(log_off + 2, old_val);
419         
420         gs := log_write_step(gs, log_off + 1, old_val).0;
421 
422         assert ghost_tx_inv(gs);
423         assert log_[0] == gs.num_entry;
424         assert log_.Length == |gs.log| + 1;
425         assert 0 <= gs.num_entry * 2 < |gs.log|;
