431              then s.(first_log_pos := s.first_log_pos[offset := log_idx])
432              else s;
433         gs := s;
434         write_mem(offset, val);
435         gs := mem_write_step(gs, offset, val).0;
436 
437         assert gs == ghost_tx_write(old_gs, offset, val);
438     }
