440     // we assume that recover won't crash (though this code works when recover can fail)
441     method recover()
442         modifies log_;
443         modifies mem_;
444         modifies this;
445         requires state_inv();
446         requires ghost_tx_inv(gs);
447         requires old_mem_equiv(gs);
448         requires ghost_state_equiv(gs);
449         ensures gs == ghost_recover(old(gs));
450         ensures ghost_state_equiv(gs);
451     {
452         var log_len := log_[0];
453         assert log_len == gs.num_entry;
454         if (log_len > 0) {
455             var i := log_len - 1;
456 
457             ghost var gs0 := gs;
458             while i >= 0
459                 modifies mem_;
460                 modifies this;
461                 invariant log_ == old(log_);
462                 invariant mem_ == old(mem_);
463                 invariant unchanged(log_);
464                 invariant -1 <= i < log_len;
465                 invariant |gs.log| == |gs0.log|;
466                 invariant ghost_state_equiv(gs);
467                 invariant ghost_tx_inv(gs);
468                 invariant old_mem_equiv(gs);
469                 invariant reverse_recovery(gs0, log_len) == reverse_recovery(gs, i + 1);
470                 decreases i;
471             {
472                 assert ghost_state_equiv(gs);
473                 assert 0 <= i < log_[0];
474                 var o := i * 2 + 1;
475                 var off := log_[o];
476                 var val := log_[o + 1];
477                 mem_[off] := val;
478                 assert 0 <= off < mem_.Length;
479 
480                 assert gs.log[i * 2] == off;
481                 assert gs.log[i * 2 + 1] == val;
482                 gs := gs.(mem := gs.mem[off := val]);
483                 i := i - 1;
484             }
485             assert ghost_state_equiv(gs);
486         } else {
487             assert ghost_state_equiv(gs);
488         }
489         log_[0] := 0;
490         gs := ghost_recover(old(gs));
491         assert ghost_state_equiv(gs);
492     }
493 }
