495 lemma crash_safe_single_tx(init_log : seq<int>, init_mem : seq<int>,
496                            countdown : int,
497                            writes : seq<(int, int)>)
498     requires |init_log| > 0;
499     requires countdown >= 0;
500     requires forall i :: 0 <= i < |writes| ==>
501                 0 <= writes[i].0 < |init_mem|;
502     requires 0 < |writes| * 2 < |init_log|;
503 {
504     var s := init_ghost_state(init_log, init_mem, countdown);
505 
506     var end_mem := init_mem;
507 
508     s := ghost_begin_tx(s);
509     assert s.num_entry == 0;
510     assert init_mem == s.old_mem;
511 
512     var i := 0;
513     while i < |writes|
514         decreases |writes| - i;
515         invariant 0 <= i <= |writes|;
516         invariant s.mem_len == |init_mem|;
517         invariant s.mem_len == |end_mem|;
518         invariant 0 <= s.num_entry <= i;
519         invariant i * 2 < |s.log|;
520         invariant 0 <= s.num_entry * 2 < |s.log|;
521         invariant ghost_tx_inv(s);
522         invariant old_mem_equiv(s);
523         invariant init_mem == s.old_mem;
524         invariant !crashed(s) ==> forall i :: 0 <= i < |s.mem| ==> s.mem[i] == end_mem[i];
525     {
526         assert 0 <= i < |writes|;
527         assert 0 <= writes[i].0 < s.mem_len;
528         assert 0 <= s.num_entry * 2 + 2 < |s.log|;
529         s := ghost_tx_write(s, writes[i].0, writes[i].1);
530 
531         end_mem := end_mem[writes[i].0 := writes[i].1];
532 
533         assert !crashed(s) ==> s.mem[writes[i].0] == writes[i].1;
534         i := i + 1;
535     }
536 
537     assert ghost_tx_inv(s);
538     assert old_mem_equiv(s);
539 
540     var (s', c) := ghost_commit_tx(s);
541     assert c ==> !crashed(s);
542 
543     if (c) {
544         assert !crashed(s);
545         assert s.mem == end_mem;
546     } else {
547         var recovered := ghost_recover(s');
548         assert recovered.mem == init_mem;
549     }
550 }

