1 class CrashableMem<T> {
2     var mem_ : array<T>;
3     method read(off : int) returns (r : T)
4         requires 0 <= off < mem_.Length;
5     {
6         return mem_[off];
7     }
8 
9     method write(off : int, val : T)
10         requires 0 <= off < mem_.Length;
11         modifies mem_;
12     {
13         mem_[off] := val;
14     }
15 }
16 
17 datatype GhostState = GS(
18     num_entry : int,
19     log : seq<int>,
20 
21     mem_len : int,
22     mem : seq<int>,
23     old_mem : seq<int>,
24     ideal_mem : seq<int>,
25     countdown : int,
26     first_log_pos : map<int, int>
27 )
28 
29 datatype GhostOp = WriteMem(off : int, val : int)
30                  | WriteLog(off : int, val : int)
31 predicate ghost_state_inv(s : GhostState) {
32     0 <= s.num_entry * 2 < |s.log|
33     && |s.log| > 0
34     && |s.mem| == s.mem_len && |s.ideal_mem| == s.mem_len && |s.old_mem| == s.mem_len
35     && s.countdown >= 0
36 }
37 
38 function init_ghost_state(log : seq<int>, mem : seq<int>, countdown : int) : GhostState
39     requires |log| > 0;
40     requires countdown >= 0;
41     ensures ghost_state_inv(init_ghost_state(log, mem, countdown));
42 {
43     GS(0, log[..], |mem|, mem[..], mem[..], mem[..], countdown, map[])
44 }
45 
46 function mem_write(s : GhostState, off: int, val: int) : GhostState
47     requires ghost_state_inv(s);
